require_once __DIR__.'/config.php';require_login();if(!fams_current_type_allows('MAIFIP','view_records')){http_response_code(403);exit('Offline conflict access is not permitted.');}$activeFacility=active_data_facility($pdo);$pageTitle='Offline Synchronization';$st=$pdo->prepare("SELECT o.*,a.control_number,a.patient_first_name,a.patient_last_name FROM offline_sync_log o JOIN assistance_records a ON a.id=o.record_id AND a.facility=? WHERE o.user_id=? AND o.status='CONFLICT' ORDER BY o.created_at DESC");$st->execute([$activeFacility,current_user()['id']]);$conflicts=$st->fetchAll();require __DIR__.'/partials/header.php'; ?>
<section class="panel form-panel offline-sync-page"><div class="panel-heading"><div><span class="section-kicker">DATA SYNCHRONIZATION</span><h3>Offline Changes &amp; Conflicts</h3></div><button type="button" class="primary-btn" onclick="window.FAMSSyncOffline?.()">Sync Now</button></div><div class="notice"><strong>Offline editing is controlled.</strong> Record-detail changes are queued on this device and synchronized with record-version checks. Conflicts are retained rather than silently overwritten.</div>
<?php if(!$conflicts): ?><div class="empty-state">No unresolved synchronization conflicts for your account.</div><?php else: ?><div class="table-wrap wide-table"><table class="fams-data-list-table"><thead><tr><th>Record</th><th>Created</th><th>Server Version</th><th>Your Base Version</th><th>Conflict</th></tr></thead><tbody><?php foreach($conflicts as $c): $j=json_decode((string)$c['conflict_json'],true)?:[]; ?><tr><td><strong><?=e($c['control_number']?:('#'.$c['record_id']))?></strong><br><?=e(trim(($c['patient_first_name']??'').' '.($c['patient_last_name']??'')))?></td><td><?=e(date('M d, Y H:i',strtotime($c['created_at'])))?></td><td><?=e((string)($j['server']['record_version']??''))?></td><td><?=e((string)$c['base_version'])?></td><td><details><summary>Review values</summary><pre><?=e(json_encode($j,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details><div class="conflict-actions"><button type="button" class="ghost-btn" onclick="window.FAMSResolveOffline('<?=e($c['client_change_id'])?>','KEEP_SERVER')">Keep Server</button><button type="button" class="primary-btn" onclick="window.FAMSResolveOffline('<?=e($c['client_change_id'])?>','USE_OFFLINE')">Use My Offline Change</button></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php require __DIR__.'/partials/footer.php'; ?>
